    36	        [transactionViolations],
    37	    );
    38	    const transactionIDs = [transactionID, ...duplicateTransactionIDs];
    39	
    40	    const transactions = transactionIDs.map((item) => TransactionUtils.getTransaction(item)).sort((a, b) => new Date(a?.created ?? '').getTime() - new Date(b?.created ?? '').getTime());
