    43	        Transaction.dismissDuplicateTransactionViolation(transactionIDs, currentPersonalDetails);
    44	        Navigation.goBack();
    45	    };
    46	
    47	    const hasSettledOrApprovedTransaction = transactions.some((transaction) => ReportUtils.isSettled(transaction?.reportID) || ReportUtils.isReportApproved(transaction?.reportID));
