    49	    return (
    50	        <ScreenWrapper testID={TransactionDuplicateReview.displayName}>
    51	            <FullPageNotFoundView shouldShow={transactionID === '-1'}>
    52	                <HeaderWithBackButton
    53	                    title={translate('iou.reviewDuplicates')}
    54	                    onBackButtonPress={() => Navigation.goBack(route.params.backTo)}
    55	                />
    56	                <View style={[styles.justifyContentCenter, styles.ph5, styles.pb3, styles.borderBottom]}>
    57	                    <Button
    58	                        text={translate('iou.keepAll')}
    59	                        onPress={keepAll}
    60	                    />
    61	                    {!!hasSettledOrApprovedTransaction && <Text style={[styles.textNormal, styles.colorMuted, styles.mt3]}>{translate('iou.someDuplicatesArePaid')}</Text>}
    62	                </View>
    63	                <DuplicateTransactionsList transactions={transactions} />
    64	            </FullPageNotFoundView>
    65	        </ScreenWrapper>
    66	    );
    67	}
